package mz.co.aprendaacodar.course.repository;import mz.co.aprendaacodar.course.entity.Course;import mz.co.aprendaacodar.common.enums.Enums.CourseStatus;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;
